-- Run as a suitably scoped Snowflake administrator. Do not use production credentials in browser code.
CREATE DATABASE IF NOT EXISTS EDUTOPIA;
CREATE SCHEMA IF NOT EXISTS EDUTOPIA.PUBLIC;
USE SCHEMA EDUTOPIA.PUBLIC;
CREATE TABLE IF NOT EXISTS ADVENTURES (ID VARCHAR, DOCUMENT VARIANT);
MERGE INTO ADVENTURES t USING (SELECT 'sdg12-addis' ID, PARSE_JSON('{"id": "sdg12-addis", "title": "A city of possibilities", "sdg": 12, "city": "Addis Ababa", "country": "Ethiopia"}') DOCUMENT) s ON t.ID=s.ID WHEN MATCHED THEN UPDATE SET DOCUMENT=s.DOCUMENT WHEN NOT MATCHED THEN INSERT (ID,DOCUMENT) VALUES (s.ID,s.DOCUMENT);
CREATE TABLE IF NOT EXISTS LEARNING_LOCATIONS (ID VARCHAR, DOCUMENT VARIANT);
MERGE INTO LEARNING_LOCATIONS t USING (SELECT 'market' ID, PARSE_JSON('{"id": "market", "adventure_id": "sdg12-addis", "title": "Neighborhood Market", "fictional": true}') DOCUMENT) s ON t.ID=s.ID WHEN MATCHED THEN UPDATE SET DOCUMENT=s.DOCUMENT WHEN NOT MATCHED THEN INSERT (ID,DOCUMENT) VALUES (s.ID,s.DOCUMENT);
MERGE INTO LEARNING_LOCATIONS t USING (SELECT 'sorting' ID, PARSE_JSON('{"id": "sorting", "adventure_id": "sdg12-addis", "title": "Community Sorting Station", "fictional": true}') DOCUMENT) s ON t.ID=s.ID WHEN MATCHED THEN UPDATE SET DOCUMENT=s.DOCUMENT WHEN NOT MATCHED THEN INSERT (ID,DOCUMENT) VALUES (s.ID,s.DOCUMENT);
CREATE TABLE IF NOT EXISTS LESSONS (ID VARCHAR, DOCUMENT VARIANT);
MERGE INTO LESSONS t USING (SELECT 'prevention' ID, PARSE_JSON('{"id": "prevention", "location_id": "market", "title": "Before the bin", "objectives": ["Distinguish prevention from waste management", "Connect packaging choices to waste generation"], "skill_ids": ["environment", "critical"]}') DOCUMENT) s ON t.ID=s.ID WHEN MATCHED THEN UPDATE SET DOCUMENT=s.DOCUMENT WHEN NOT MATCHED THEN INSERT (ID,DOCUMENT) VALUES (s.ID,s.DOCUMENT);
MERGE INTO LESSONS t USING (SELECT 'systems' ID, PARSE_JSON('{"id": "systems", "location_id": "sorting", "title": "Beyond the bin", "objectives": ["Connect separation, collection, and processing", "Recognize service-specific acceptance rules"], "skill_ids": ["systems", "planning"]}') DOCUMENT) s ON t.ID=s.ID WHEN MATCHED THEN UPDATE SET DOCUMENT=s.DOCUMENT WHEN NOT MATCHED THEN INSERT (ID,DOCUMENT) VALUES (s.ID,s.DOCUMENT);
CREATE TABLE IF NOT EXISTS SKILLS (ID VARCHAR, DOCUMENT VARIANT);
MERGE INTO SKILLS t USING (SELECT 'systems' ID, PARSE_JSON('{"id": "systems", "title": "Systems thinking"}') DOCUMENT) s ON t.ID=s.ID WHEN MATCHED THEN UPDATE SET DOCUMENT=s.DOCUMENT WHEN NOT MATCHED THEN INSERT (ID,DOCUMENT) VALUES (s.ID,s.DOCUMENT);
MERGE INTO SKILLS t USING (SELECT 'environment' ID, PARSE_JSON('{"id": "environment", "title": "Environmental literacy"}') DOCUMENT) s ON t.ID=s.ID WHEN MATCHED THEN UPDATE SET DOCUMENT=s.DOCUMENT WHEN NOT MATCHED THEN INSERT (ID,DOCUMENT) VALUES (s.ID,s.DOCUMENT);
MERGE INTO SKILLS t USING (SELECT 'critical' ID, PARSE_JSON('{"id": "critical", "title": "Critical thinking"}') DOCUMENT) s ON t.ID=s.ID WHEN MATCHED THEN UPDATE SET DOCUMENT=s.DOCUMENT WHEN NOT MATCHED THEN INSERT (ID,DOCUMENT) VALUES (s.ID,s.DOCUMENT);
MERGE INTO SKILLS t USING (SELECT 'research' ID, PARSE_JSON('{"id": "research", "title": "Research"}') DOCUMENT) s ON t.ID=s.ID WHEN MATCHED THEN UPDATE SET DOCUMENT=s.DOCUMENT WHEN NOT MATCHED THEN INSERT (ID,DOCUMENT) VALUES (s.ID,s.DOCUMENT);
MERGE INTO SKILLS t USING (SELECT 'planning' ID, PARSE_JSON('{"id": "planning", "title": "Project planning"}') DOCUMENT) s ON t.ID=s.ID WHEN MATCHED THEN UPDATE SET DOCUMENT=s.DOCUMENT WHEN NOT MATCHED THEN INSERT (ID,DOCUMENT) VALUES (s.ID,s.DOCUMENT);
CREATE TABLE IF NOT EXISTS EDUCATIONAL_RESOURCES (ID VARCHAR, DOCUMENT VARIANT);
MERGE INTO EDUCATIONAL_RESOURCES t USING (SELECT 'un12' ID, PARSE_JSON('{"id": "un12", "lesson_id": "prevention", "title": "UN Sustainable Development Goal 12", "url": "https://sdgs.un.org/goals/goal12", "category": "general-background"}') DOCUMENT) s ON t.ID=s.ID WHEN MATCHED THEN UPDATE SET DOCUMENT=s.DOCUMENT WHEN NOT MATCHED THEN INSERT (ID,DOCUMENT) VALUES (s.ID,s.DOCUMENT);
CREATE TABLE IF NOT EXISTS CURRICULUM_MODULES (ID VARCHAR, DOCUMENT VARIANT);
MERGE INTO CURRICULUM_MODULES t USING (SELECT 'sdg12-addis' ID, PARSE_JSON('{"adventures": [{"id": "sdg12-addis", "title": "A city of possibilities", "sdg": 12, "city": "Addis Ababa", "country": "Ethiopia"}], "locations": [{"id": "market", "adventure_id": "sdg12-addis", "title": "Neighborhood Market", "fictional": true}, {"id": "sorting", "adventure_id": "sdg12-addis", "title": "Community Sorting Station", "fictional": true}], "lessons": [{"id": "prevention", "location_id": "market", "title": "Before the bin", "objectives": ["Distinguish prevention from waste management", "Connect packaging choices to waste generation"], "skill_ids": ["environment", "critical"]}, {"id": "systems", "location_id": "sorting", "title": "Beyond the bin", "objectives": ["Connect separation, collection, and processing", "Recognize service-specific acceptance rules"], "skill_ids": ["systems", "planning"]}], "skills": [{"id": "systems", "title": "Systems thinking"}, {"id": "environment", "title": "Environmental literacy"}, {"id": "critical", "title": "Critical thinking"}, {"id": "research", "title": "Research"}, {"id": "planning", "title": "Project planning"}], "resources": [{"id": "un12", "lesson_id": "prevention", "title": "UN Sustainable Development Goal 12", "url": "https://sdgs.un.org/goals/goal12", "category": "general-background"}]}') DOCUMENT) s ON t.ID=s.ID WHEN MATCHED THEN UPDATE SET DOCUMENT=s.DOCUMENT WHEN NOT MATCHED THEN INSERT (ID,DOCUMENT) VALUES (s.ID,s.DOCUMENT);
